    } else if (ch === '.') {
      let j = i + 1
      while (isNameChar(s[j])) j++
      if (j > i + 1) b += 1
      i = j
    } else if (ch === '[') {
      let j = i + 1
      while (j < s.length && s[j] !== ']') j++
