      // 视口是默认参照，但如果祖先带 transform/filter/contain，它就变成包含块
      if (isolated) return i
      continue
    }
    if (position === 'absolute') {
      if (positioned || isolated) return i
      continue
    }
    if (position === 'sticky') {
      // 粘性定位的参照物是最近的滚动容器
      if (a.overflow != null && a.overflow !== 'visible') return i
      continue
    }
    // static / relative 不脱标：交给正常流父元素
