      if (next < 0) next = 0
      delivered += next - sizes[i]
      sizes[i] = next
      if (next === tracks[i].floor) frozen[i] = true
    }
    spare -= delivered
    if (Math.abs(delivered) < 0.001) break
  }

  return sizes.map((s) => round2(s))
}

