  '--brand': '#3b82f6',
  '--text': 'var(--brand)',
  '--border': 'var(--brand-dark, #dbeafe)'
}
console.log(resolveToken('--text', theme))    // '#3b82f6'
console.log(resolveToken('--border', theme))  // '#dbeafe'（fallback 生效）

